import"../../panels/coverage/coverage-legacy.js";import"../sources_test_runner/sources_test_runner.js";import{TestRunner}from"../test_runner/test_runner.js";export const CoverageTestRunner={};CoverageTestRunner.startCoverage=async function(e){self.UI.viewManager.showView("coverage");const r=Coverage.CoverageView.instance();await r.startRecording({reload:!1,jsCoveragePerBlock:e})},CoverageTestRunner.stopCoverage=function(){return Coverage.CoverageView.instance().stopRecording()},CoverageTestRunner.suspendCoverageModel=async function(){const e=Coverage.CoverageView.instance();await e.model.preSuspendModel(),await e.model.suspendModel()},CoverageTestRunner.resumeCoverageModel=async function(){const e=Coverage.CoverageView.instance();await e.model.resumeModel(),await e.model.postResumeModel()},CoverageTestRunner.pollCoverage=async function(){const e=Coverage.CoverageView.instance();return await e.model.currentPollPromise,e.model.pollAndCallback()},CoverageTestRunner.getCoverageModel=function(){return Coverage.CoverageView.instance().model},CoverageTestRunner.exportReport=async function(){const e=Coverage.CoverageView.instance();let r;return await e.model.exportReport({write:e=>{r=e},close:e=>0}),r},CoverageTestRunner.sourceDecorated=async function(e){await self.UI.inspectorView.showPanel("sources");const r=TestRunner.addSnifferPromise(Coverage.CoverageView.LineDecorator.prototype,"innerDecorate"),o=await SourcesTestRunner.showScriptSourcePromise(e);return await r,o},CoverageTestRunner.dumpDecorations=async function(e){const r=await CoverageTestRunner.sourceDecorated(e);CoverageTestRunner.dumpDecorationsInSourceFrame(r)},CoverageTestRunner.findCoverageNodeForURL=function(e){const r=Coverage.CoverageView.instance().listView.dataGrid.rootNode();for(const o of r.children)if(o.coverageInfo.url().endsWith(e))return o;return null},CoverageTestRunner.dumpDecorationsInSourceFrame=function(e){const r=new Map([["used","+"],["unused","-"]]),o=e.textEditor.codeMirror();for(let e=0;e<o.lineCount();++e){const n=o.getLine(e);let t=" ";const a=o.lineInfo(e);if(!a)continue;const s=a.gutterMarkers&&a.gutterMarkers["CodeMirror-gutter-coverage"];if(s){const e=/^text-editor-coverage-(\w*)-marker$/.exec(s.classList)[1];t=r.get(e)||s.classList}TestRunner.addResult(`${e}: ${t} ${n}`)}},CoverageTestRunner.dumpCoverageListView=function(){const e=Coverage.CoverageView.instance().listView.dataGrid;e.updateInstantly();for(const r of e.rootNode().children){const e=r.coverageInfo,o=TestRunner.formatters.formatAsURL(e.url());if(o.startsWith("test://"))continue;const n=Coverage.coverageTypeToString(e.type());TestRunner.addResult(`${o} ${n} used: ${e.usedSize()} unused: ${e.unusedSize()} total: ${e.size()}`)}};